fn frame(t: i32) {
    let mut period: i32 = host::display::state_get(0);
    if period == 0 { period = 30; }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if py >= 400 && py < 460 {
            if px >= 60 && px < 160 { period = period + 5; }
            if px >= 290 && px < 390 { period = period - 5; }
        }
    }
    if period < 10 { period = 10; }
    if period > 90 { period = 90; }
    host::display::state_set(0, period);
    host::display::state_set(1, down);
    let mut phase: i32 = host::display::state_get(2) + 1;
    let mut beat: i32 = host::display::state_get(3);
    if phase >= period {
        phase = 0;
        beat = (beat + 1) % 4;
        if beat == 0 {
            host::audio::tone(1320, 50, 1);
        } else {
            host::audio::tone(880, 35, 1);
        }
    }
    host::display::state_set(2, phase);
    host::display::state_set(3, beat);
    host::display::clear(0x101014);
    host::display::draw_string(60, 40, "BPM", 0x808080, 2);
    host::display::draw_number(130, 40, 3600 / period, 0xffffff, 3);
    let mut i: i32 = 0;
    while i < 4 {
        let mut c: i32 = 0x282830;
        if i == beat {
            if i == 0 { c = 0xff5040; } else { c = 0xffff40; }
        }
        host::display::fill_rect(60 + i * 90, 150, 60, 60, c);
        i = i + 1;
    }
    host::display::fill_rect(60, 400, 100, 60, 0x203040);
    host::display::fill_rect(290, 400, 100, 60, 0x203040);
    host::display::draw_string(78, 420, "SLOW", 0xffffff, 2);
    host::display::draw_string(308, 420, "FAST", 0xffffff, 2);
    host::display::present();
}
